/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: VideoGridView
 *   Classes: VideoPageError
 *   Functions: readVideoGridDefinition, readVideoGridState, readVideoGridPageTracks, encodeVideoGridCursor,
 *              decodeVideoGridCursor, isVideoGridCursor, systemAdminPage
 *   Constants: maximumAdminVideoGridItems, videoGridCollectionId, videoGridPageItemId
 * Internal
 *   Functions: revisionFor, publicationTime
 *   Constants: videoProjection, videoMembershipProjection
 * @end-catalog */

import { createHash, createHmac, timingSafeEqual } from 'node:crypto';
import { ObjectId, type ClientSession } from 'mongodb';
import { getDb } from '../../infrastructure/database';
import { findPublicAudioTracks } from '../catalog/catalogVisibilityService';
import { isPublicCatalogVisibility } from '../catalog/catalogVisibilityService';
import { getJwtSecret } from '../auth/authSessionService';

export type VideoGridView = 'grid' | 'immersive';
export const maximumAdminVideoGridItems = 5000;
// Reserved identities make an unconfigured Page reviewable without writing during a read.
export const videoGridCollectionId = '00000000000000000000f101';
export const videoGridPageItemId = '00000000000000000000f102';

/** Video configuration failures never fall back to an unrelated or partially saved definition. */
export class VideoPageError extends Error {
    constructor(readonly statusCode: number, readonly code: string) { super(code); }
}

/** Public track fields needed by the shared listener summary; private lifecycle data is never returned directly. */
const videoProjection = { _id: 1, title: 1, visibility: 1, coverArtId: 1, coverArtUrl: 1,
    artistIds: 1, albumId: 1, duration: 1, mediaType: 1, contentType: 1, s3Key: 1,
    videoAsset: 1, releaseDate: 1, credits: 1, attributionStatus: 1, personalAttribution: 1,
    publicationUpdatedAt: 1, createdAt: 1 };
const videoMembershipProjection = { _id: 1, publicationUpdatedAt: 1, createdAt: 1 };

/** Uses the same opaque revision grammar as administrator catalog commands. */
const revisionFor = (state: unknown) => 'cr_' + createHash('sha256').update(JSON.stringify(state)).digest('base64url');

/** Later publication finishes append later, even when their original upload IDs are older. */
const publicationTime = (track: any) => {
    for (const value of [track.publicationUpdatedAt, track.createdAt]) {
        const millis = value instanceof Date ? value.getTime() : typeof value === 'string' ? Date.parse(value) : NaN;
        if (Number.isFinite(millis)) return millis;
    }
    return track._id.getTimestamp().getTime();
};

/** Resolves the persisted singleton or its non-persisted default without changing either. */
export const readVideoGridDefinition = async (session?: ClientSession) => {
    const page = await getDb()!.collection('pages').findOne({ slug: 'videos' }, { session, maxTimeMS: 3000 });
    if (!page) return { page: null, collection: null, itemId: videoGridPageItemId, collectionId: videoGridCollectionId,
        defaultView: 'grid' as VideoGridView, savedIds: [] as string[] };
    const item = Array.isArray(page.items) && page.items.length === 1 ? page.items[0] : null;
    if (!isPublicCatalogVisibility(page) || !isPublicCatalogVisibility(item)
        || item?.itemType !== 'grid' || !/^[a-f0-9]{24}$/.test(item.collectionId ?? '')
        || !/^[a-f0-9]{24}$/.test(item.itemId ?? '')) throw new VideoPageError(409, 'VIDEO_GRID_CONFIGURATION_INVALID');
    const collection = await getDb()!.collection('contentCollections').findOne({ _id: new ObjectId(item.collectionId) }, { session, maxTimeMS: 3000 });
    if (!collection || collection.presentation !== 'grid' || collection.mode !== 'dynamic'
        || collection.contentType !== 'audioTrack' || collection.dynamicSource !== 'publicVideos'
        || !['grid', 'immersive'].includes(collection.videoView) || !Array.isArray(collection.items)
        || collection.items.length > maximumAdminVideoGridItems) throw new VideoPageError(409, 'VIDEO_GRID_CONFIGURATION_INVALID');
    const savedIds = collection.items.map((ref: any) => ref?.contentType === 'audioTrack' ? ref.contentId : null);
    if (savedIds.some((id: unknown) => typeof id !== 'string' || !/^[a-f0-9]{24}$/.test(id))
        || new Set(savedIds).size !== savedIds.length) throw new VideoPageError(409, 'VIDEO_GRID_CONFIGURATION_INVALID');
    return { page, collection, itemId: item.itemId as string, collectionId: item.collectionId as string,
        defaultView: collection.videoView as VideoGridView, savedIds: savedIds as string[] };
};

/** Public scans carry only membership/order fields; complete metadata is bounded to an admin snapshot or one listener page. */
export const readVideoGridState = async (session?: ClientSession, adminBound = false) => {
    const definition = await readVideoGridDefinition(session);
    const query = findPublicAudioTracks({ mediaType: 'video', _id: { $type: 'objectId' } }, session)
        .project(adminBound ? videoProjection : videoMembershipProjection).sort({ _id: 1 }).maxTimeMS(3000);
    if (adminBound) query.limit(maximumAdminVideoGridItems + 1);
    const candidates = await query.toArray();
    if (adminBound && candidates.length > maximumAdminVideoGridItems) throw new VideoPageError(409, 'ADMIN_VIDEO_GRID_CAPACITY');
    const byId = new Map(candidates.map(track => [String(track._id), track]));
    const saved = new Set(definition.savedIds);
    const appended = candidates.filter(track => !saved.has(String(track._id))).sort((left, right) =>
        publicationTime(left) - publicationTime(right) || String(left._id).localeCompare(String(right._id)));
    const tracks = definition.collection
        ? [...definition.savedIds.flatMap(id => byId.has(id) ? [byId.get(id)!] : []), ...appended]
        : [...candidates].reverse();
    const revision = revisionFor({ page: definition.page ? { title: definition.page.title, items: definition.page.items } : null,
        collection: definition.collection ? { id: definition.collectionId, name: definition.collection.name,
            items: definition.collection.items, videoView: definition.defaultView } : null, tracks });
    return { ...definition, tracks, revision };
};

/** Rechecks the selected page's effective access and hydrates only its bounded set of Video cards. */
export const readVideoGridPageTracks = async (ids: string[]) => {
    if (ids.length === 0) return [];
    if (ids.length > 48 || ids.some(id => !/^[a-f0-9]{24}$/.test(id))) throw new VideoPageError(400, 'invalid_video_page');
    const tracks = await findPublicAudioTracks({ mediaType: 'video', _id: { $in: ids.map(id => new ObjectId(id)) } })
        .project(videoProjection).limit(ids.length).maxTimeMS(3000).toArray();
    const byId = new Map(tracks.map(track => [String(track._id), track]));
    if (byId.size !== ids.length || ids.some(id => !byId.has(id))) throw new VideoPageError(409, 'stale_video_cursor');
    return ids.map(id => byId.get(id)!);
};

/** A bounded signed cursor binds an anchor to the complete effective order and configuration. */
export const encodeVideoGridCursor = (revision: string, index: number, id: string) => {
    const payload = Buffer.from(JSON.stringify([revision, index, id])).toString('base64url');
    const signature = createHmac('sha256', getJwtSecret()).update('video-grid-v1\0' + payload).digest('base64url');
    return `vg1.${payload}.${signature}`;
};

/** Validates the full cursor before it can be used as a database position. */
export const decodeVideoGridCursor = (value: string) => {
    if (value.length > 512 || !/^vg1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]{43}$/.test(value)) throw new VideoPageError(400, 'invalid_video_cursor');
    const [, payload, signature] = value.split('.');
    const expected = createHmac('sha256', getJwtSecret()).update('video-grid-v1\0' + payload).digest('base64url');
    if (!timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) throw new VideoPageError(400, 'invalid_video_cursor');
    let decoded: unknown;
    try { decoded = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')); } catch { throw new VideoPageError(400, 'invalid_video_cursor'); }
    if (!Array.isArray(decoded) || decoded.length !== 3 || !/^cr_[A-Za-z0-9_-]{43}$/.test(decoded[0])
        || !Number.isSafeInteger(decoded[1]) || decoded[1] < 0 || !/^[a-f0-9]{24}$/.test(decoded[2])) throw new VideoPageError(400, 'invalid_video_cursor');
    return { revision: decoded[0] as string, index: decoded[1] as number, id: decoded[2] as string };
};

/** Syntactic admission stays independent of database state and secret availability. */
export const isVideoGridCursor = (value: string) => value.length <= 512 && /^vg1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]{43}$/.test(value);

/** Exposes system pages through the existing placement inventory without inventing content for Search. */
export const systemAdminPage = async (slug: 'videos' | 'search', session: ClientSession) => {
    if (slug === 'search') return { slug, title: 'Search', revision: revisionFor(['search', 1]), items: [] };
    const state = await readVideoGridDefinition(session);
    return { slug, title: 'Videos', revision: revisionFor([state.itemId, state.collectionId, state.defaultView, state.savedIds]), items: [
        { itemId: state.itemId, itemType: 'grid' as const, visibility: 'public' as const, order: 0,
            referenceId: state.collectionId, name: state.collection?.name ?? 'Videos', sourceMode: 'dynamic' as const, referenceStatus: 'ready' as const }
    ] };
};
